describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // subtotal=1000: 10% → 100, fixed → 200, sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("order does not matter in sum mode", () => {
      const a = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      const b = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100), new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(a.computeDiscountCents(5000)).toBe(b.computeDiscountCents(5000));
    });

    it("can exceed subtotal (caller clamps)", () => {
      // Two 60% discounts → sum = 120% of subtotal
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(60), new PercentageDiscountPolicy(60)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });

    it("defaults to sum mode when mode not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially against remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // subtotal=1000: 10% of 1000 → 100, remaining=900; fixed 200 of 900 → 200; total=300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("order matters in chain mode", () => {
      const ab = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(50)],
        "chain",
      );
      const ba = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // ab: fixed 500 on 1000→remaining 500, 50% of 500→250, total=750
      // ba: 50% of 1000→500, remaining 500, fixed 500 on 500→500, total=1000
      expect(ab.computeDiscountCents(1000)).toBe(750);
      expect(ba.computeDiscountCents(1000)).toBe(1000);
    });

    it("stops accumulating when remaining hits 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      // fixed eats entire 1000, remaining=0, 50% of 0 = 0
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

