describe("Cart – pricing pipeline", () => {
  it("subtotal is sum of unitPrice * quantity", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2000
    cart.add(gadget, 1); // 2000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(4000);
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("discount is applied before tax (tax on discounted subtotal)", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(50), // 50% off
      taxCalculator: new RegionalTaxCalculator({ US: 0.1 }),
      region: "US",
    });
    cart.add(widget, 1); // subtotal=1000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(1000);
    expect(t.discountCents).toBe(500);
    // tax on 500 at 10% = 50
    expect(t.taxCents).toBe(50);
  });

  it("discount is clamped to [0, subtotal]", () => {
    // Policy that returns more than subtotal
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 999999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
  });

  it("negative discount is clamped to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
  });

  it("shipping is computed against discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(500),
      shippingCalculator: new FlatShippingCalculator(300, 600),
    });
    cart.add(widget, 1); // subtotal=1000, discount=500, discountedSubtotal=500
    const t = cart.totals();
    // 500 < 600 threshold → shipping = 300
    expect(t.shippingCents).toBe(300);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ US: 0.08 }),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(widget, 2); // subtotal=2000
    const t = cart.totals();
    // discount = 10% of 2000 = 200
    // discounted = 1800
    // tax = 8% of 1800 = 144
    // shipping = 500
    // total = 1800 + 144 + 500 = 2444
    expect(t.discountCents).toBe(200);
    expect(t.taxCents).toBe(144);
    expect(t.shippingCents).toBe(500);
    expect(t.totalCents).toBe(2444);
  });

  it("uses default seams (no discount, no tax, free shipping)", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });

  it("negative tax is clamped to 0", () => {
    const negTax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: negTax });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("negative shipping is clamped to 0", () => {
    const negShip: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negShip });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

