    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.message).toContain("insufficient stock");
      expect(ie.available).toBe(1);
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for a positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("rejects negative percent", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects percent > 100", () => {
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
  });

  it("rejects NaN", () => {
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
  });

  it("rejects Infinity", () => {
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts 0%", () => {
    const p = new PercentageDiscountPolicy(0);
    expect(p.computeDiscountCents(10000)).toBe(0);
  });

  it("accepts 100%", () => {
    const p = new PercentageDiscountPolicy(100);
    expect(p.computeDiscountCents(10000)).toBe(10000);
  });

  it("computes 10% of 10000 = 1000", () => {
    const p = new PercentageDiscountPolicy(10);
    expect(p.computeDiscountCents(10000)).toBe(1000);
  });

  it("floors fractional cents (e.g. 33% of 100 = 33)", () => {
    const p = new PercentageDiscountPolicy(33);
    expect(p.computeDiscountCents(100)).toBe(33);
  });

  it("floors down (15% of 999 = 149)", () => {
    const p = new PercentageDiscountPolicy(15);
    // 999 * 15 / 100 = 149.85 → 149
    expect(p.computeDiscountCents(999)).toBe(149);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(-100)).toBe(0);
  });

  it("handles very large subtotal", () => {
    const p = new PercentageDiscountPolicy(25);
    expect(p.computeDiscountCents(1_000_000_00)).toBe(25_000_000);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("rejects negative amount", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects non-integer amount", () => {
    expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
  });

  it("accepts 0", () => {
    const p = new FixedAmountDiscountPolicy(0);
    expect(p.computeDiscountCents(500)).toBe(0);
  });

  it("returns the fixed amount when subtotal exceeds it", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(1000)).toBe(500);
  });

  it("caps at subtotal when fixed amount exceeds subtotal", () => {
    const p = new FixedAmountDiscountPolicy(2000);
    expect(p.computeDiscountCents(500)).toBe(500);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // subtotal=1000: 10% → 100, fixed → 200, sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("order does not matter in sum mode", () => {
      const a = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      const b = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100), new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(a.computeDiscountCents(5000)).toBe(b.computeDiscountCents(5000));
    });

    it("can exceed subtotal (caller clamps)", () => {
      // Two 60% discounts → sum = 120% of subtotal
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(60), new PercentageDiscountPolicy(60)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });

    it("defaults to sum mode when mode not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially against remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // subtotal=1000: 10% of 1000 → 100, remaining=900; fixed 200 of 900 → 200; total=300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("order matters in chain mode", () => {
      const ab = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(50)],
        "chain",
      );
      const ba = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // ab: fixed 500 on 1000→remaining 500, 50% of 500→250, total=750
      // ba: 50% of 1000→500, remaining 500, fixed 500 on 500→500, total=1000
      expect(ab.computeDiscountCents(1000)).toBe(750);
      expect(ba.computeDiscountCents(1000)).toBe(1000);
    });

    it("stops accumulating when remaining hits 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      // fixed eats entire 1000, remaining=0, 50% of 0 = 0
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

