      },
      {
        product: { id: "b", name: "B", unitPriceCents: 200, weightGrams: 300 },
        quantity: 3,
      },
    ];
    // 500*2 + 300*3 = 1900
    expect(totalLineWeightGrams(lines)).toBe(1900);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });
});

import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const line = (
  id: string,
  price: number,
  qty: number,
  weight?: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: price, weightGrams: weight },
  quantity: qty,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([line("a", 100, 1)], 100)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("rejects negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("rejects non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(10.5)).toThrow(RangeError);
  });

  it("rejects negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("rejects non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 99.5)).toThrow(RangeError);
  });

  it("returns flat rate for non-empty cart", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([line("a", 100, 1)], 100)).toBe(599);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 when subtotal meets free-over threshold", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([line("a", 5000, 1)], 5000)).toBe(0);
  });

  it("returns 0 when subtotal exceeds free-over threshold", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([line("a", 6000, 1)], 6000)).toBe(0);
  });

  it("returns flat rate when subtotal below threshold", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([line("a", 4999, 1)], 4999)).toBe(599);
  });

  it("accepts 0 flatCents", () => {
    const calc = new FlatShippingCalculator(0);
    expect(calc.computeShippingCents([line("a", 100, 1)], 100)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer upToGrams", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator([
          { upToGrams: 1.5, costCents: 100 },
        ]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer costCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator([
          { upToGrams: 1000, costCents: 1.5 },
        ]),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 100 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 100 }],
          5.5,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 for items with no weight", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([line("a", 100, 2)], 200)).toBe(0);
  });

  it("selects the correct bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 900 },
    ]);
    // 200g item, qty 2 → 400g → bracket 500
    expect(calc.computeShippingCents([line("a", 100, 2, 200)], 200)).toBe(300);
  });

  it("selects bracket at exact boundary", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    // exactly 500g → first bracket
    expect(calc.computeShippingCents([line("a", 100, 1, 500)], 100)).toBe(300);
  });

  it("moves to next bracket when weight exceeds boundary", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    // 501g → second bracket
    expect(calc.computeShippingCents([line("a", 100, 1, 501)], 100)).toBe(500);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ],
      1200,
    );
    expect(calc.computeShippingCents([line("a", 100, 1, 1500)], 100)).toBe(
      1200,
    );
  });

  it("defaults overflow to heaviest bracket cost", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([line("a", 100, 1, 1500)], 100)).toBe(500);
  });

  it("sorts brackets regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 500, costCents: 300 },
    ]);
    // 400g → should hit the 500g bracket (300)
    expect(calc.computeShippingCents([line("a", 100, 1, 400)], 100)).toBe(300);
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("InventoryError", () => {
  it("exposes productId, requested, and available", () => {
    const err = new InventoryError("out of stock", "p1", 5, 2);
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("p1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
    expect(err.name).toBe("InventoryError");
    expect(err).toBeInstanceOf(Error);
  });

  it("available can be undefined", () => {
    const err = new InventoryError("gone", "p2", 1, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  const lines: CartLine[] = [
    {
      product: { id: "p1", name: "Widget", unitPriceCents: 100 },
      quantity: 2,
    },
    {
      product: { id: "p2", name: "Gadget", unitPriceCents: 200 },
      quantity: 1,
    },
  ];

  it("updates prices from the fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation((id: string) => {
        if (id === "p1") return Promise.resolve(150);
        return Promise.resolve(250);
      }),
    };
    const result = await refreshPrices(lines, fetcher);
    expect(result).toHaveLength(2);
    expect(result[0]!.product.unitPriceCents).toBe(150);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.product.unitPriceCents).toBe(250);
  });

  it("preserves other product fields", async () => {
    const linesWithWeight: CartLine[] = [
      {
        product: {
          id: "p1",
          name: "Widget",
          unitPriceCents: 100,
          weightGrams: 500,
          currency: "EUR",
        },
        quantity: 1,
      },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(300),
    };
    const result = await refreshPrices(linesWithWeight, fetcher);
    expect(result[0]!.product.weightGrams).toBe(500);
    expect(result[0]!.product.currency).toBe("EUR");
    expect(result[0]!.product.name).toBe("Widget");
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("fetch failed");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
} from "../src/pricing.ts";
import { RegionalTaxCalculator, NoTaxCalculator } from "../src/tax.ts";
import {
  FlatShippingCalculator,
  FreeShippingCalculator,
} from "../src/shipping.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const widget: Product = { id: "w", name: "Widget", unitPriceCents: 1000 };
const gadget: Product = { id: "g", name: "Gadget", unitPriceCents: 2000 };

describe("Cart – line management", () => {
  it("add creates a new line", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(cart.itemCount).toBe(1);
  });

  it("add merges quantities for the same product", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add rejects non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, 0)).toThrow(RangeError);
    expect(() => cart.add(widget, -1)).toThrow(RangeError);
  });

  it("add rejects non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
  });

  it("add rejects negative unitPriceCents", () => {
    const cart = new Cart();
    const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true and removes line", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(cart.remove("w")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(widget, 3);
    cart.updateQuantity("w", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(widget, 3);
    cart.updateQuantity("w", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w", 1.5)).toThrow(RangeError);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("x", 1)).toThrow(
      "Product x is not in the cart",
    );
  });

  it("clear removes all lines", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    cart.add(gadget, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const snap = cart.snapshot();
    // Mutating snapshot should not affect internal state
    (snap[0] as any).quantity = 999;
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart – pricing pipeline", () => {
  it("subtotal is sum of unitPrice * quantity", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2000
    cart.add(gadget, 1); // 2000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(4000);
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("discount is applied before tax (tax on discounted subtotal)", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(50), // 50% off
      taxCalculator: new RegionalTaxCalculator({ US: 0.1 }),
      region: "US",
    });
    cart.add(widget, 1); // subtotal=1000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(1000);
    expect(t.discountCents).toBe(500);
    // tax on 500 at 10% = 50
    expect(t.taxCents).toBe(50);
  });

  it("discount is clamped to [0, subtotal]", () => {
    // Policy that returns more than subtotal
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 999999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
  });

  it("negative discount is clamped to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
  });

  it("shipping is computed against discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(500),
      shippingCalculator: new FlatShippingCalculator(300, 600),
    });
    cart.add(widget, 1); // subtotal=1000, discount=500, discountedSubtotal=500
    const t = cart.totals();
    // 500 < 600 threshold → shipping = 300
    expect(t.shippingCents).toBe(300);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ US: 0.08 }),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(widget, 2); // subtotal=2000
    const t = cart.totals();
    // discount = 10% of 2000 = 200
    // discounted = 1800
    // tax = 8% of 1800 = 144
    // shipping = 500
    // total = 1800 + 144 + 500 = 2444
    expect(t.discountCents).toBe(200);
    expect(t.taxCents).toBe(144);
    expect(t.shippingCents).toBe(500);
    expect(t.totalCents).toBe(2444);
  });

  it("uses default seams (no discount, no tax, free shipping)", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });

  it("negative tax is clamped to 0", () => {
    const negTax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: negTax });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("negative shipping is clamped to 0", () => {
    const negShip: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negShip });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

describe("Cart – checkout()", () => {
  it("returns totals and lines for a basic checkout", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher before computing totals", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    // Price updated from 1000 to 1500, qty=2 → subtotal=3000
    expect(result.totals.subtotalCents).toBe(3000);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("w");
  });

  it("checks inventory and throws InventoryError on denial", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "OOS" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("w");
      expect(ie.requested).toBe(5);
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(widget, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("w");
      expect(ie.requested).toBe(10);
      expect(ie.available).toBe(3);
    }
  });

  it("passes when inventory says available with sufficient quantity", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 10,
      }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("passes when availableQuantity is exactly the requested amount", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 5,
      }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(5000);
  });

  it("uses asyncTaxProvider for tax calculation", async () => {
    const cart = new Cart({
      discountPolicy: new NoDiscountPolicy(),
      region: "US-CA",
    });
    cart.add(widget, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // 1000 * 0.0875 = 87.5 → 87
    expect(result.totals.taxCents).toBe(87);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("async tax provider with discount and shipping composition", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(20),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(widget, 3); // subtotal=3000
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // discount = 20% of 3000 = 600, discounted=2400
    // tax = 10% of 2400 = 240
    // shipping = 500
    // total = 2400 + 240 + 500 = 3140
    expect(result.totals.discountCents).toBe(600);
    expect(result.totals.taxCents).toBe(240);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(3140);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart({ region: "US" });
    cart.add(widget, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("combined: price refresh + inventory + async tax", async () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(100),
      shippingCalculator: new FreeShippingCalculator(),
      region: "US",
    });
    cart.add(widget, 1);
    cart.add(gadget, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation((id: string) => {
        if (id === "w") return Promise.resolve(1200);
        return Promise.resolve(2500);
      }),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // subtotal = 1200 + 2500 = 3700
    // discount = min(100, 3700) = 100
    // discounted = 3600
    // tax = 5% of 3600 = 180
    // shipping = 0
    // total = 3600 + 180 = 3780
    expect(result.totals.subtotalCents).toBe(3700);
    expect(result.totals.discountCents).toBe(100);
    expect(result.totals.taxCents).toBe(180);
    expect(result.totals.totalCents).toBe(3780);
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });

  it("checkout with no collaborators uses sync pipeline", async () => {
    const cart = new Cart({
      taxCalculator: new RegionalTaxCalculator({ US: 0.1 }),
      region: "US",
    });
    cart.add(widget, 1);
